import {
  defaultTarget,
  deployAnswer,
  deployCommands,
  deployRequest,
  parseBuildScript,
  parseTarget,
  registryImage,
  splitImage,
  targetEnvironment,
  targetValue,
} from "./deploy-product";

// What gearbox 0.1.0 writes for a kubernetes profile (the shape, trimmed).
const BUILD_SH = `#!/bin/sh
# GENERATED by gearbox 0.1.0 -- do not edit. Run \`gearbox generate\` to regenerate.
set -eu
SCRIPT_DIR=$(CDPATH= cd -- "$(dirname "$0")" && pwd)
CONTEXT=$(CDPATH= cd -- "$SCRIPT_DIR/"'../../../../..' && pwd)
export DOCKER_BUILDKIT=1
build_one() {
  name=$1
  image=$2
  docker build \\
    --ignorefile "$SCRIPT_DIR/.dockerignore" \\
    -f "$SCRIPT_DIR/$name/Dockerfile" \\
    -t "$image" \\
    "$CONTEXT"
}

if [ "$#" -eq 0 ]; then
  build_one api-gateway 'gbx-api-gateway:0.1.0'
  build_one worker 'gbx-worker:0.1.0'
  exit 0
fi

for name in "$@"; do
  case "$name" in
    api-gateway) build_one api-gateway 'gbx-api-gateway:0.1.0' ;;
    worker) build_one worker 'gbx-worker:0.1.0' ;;
    *) echo "unknown application: $name" >&2; exit 1 ;;
  esac
done
`;

describe("the generated build script", () => {
  it("names the build context and every application's image", () => {
    expect(parseBuildScript(BUILD_SH)).toEqual({
      contextFromDocker: "../../../../..",
      images: [
        { app: "api-gateway", image: "gbx-api-gateway:0.1.0" },
        { app: "worker", image: "gbx-worker:0.1.0" },
      ],
    });
  });

  it("is not guessed at when it is not the engine's shape", () => {
    expect(parseBuildScript("#!/bin/sh\necho hi\n")).toBeUndefined();
  });
});

describe("image names", () => {
  it("puts the profile's registry in front, and leaves them alone without one", () => {
    expect(registryImage("gbx-api-gateway:0.1.0", "registry.example.com/team/")).toBe("registry.example.com/team/gbx-api-gateway:0.1.0");
    expect(registryImage("gbx-api-gateway:0.1.0", null)).toBe("gbx-api-gateway:0.1.0");
  });

  it("splits the tag, not a registry's port", () => {
    expect(splitImage("registry:5000/gbx-api-gateway:0.1.0")).toEqual({ repository: "registry:5000/gbx-api-gateway", tag: "0.1.0" });
    expect(splitImage("registry:5000/gbx-api-gateway")).toEqual({ repository: "registry:5000/gbx-api-gateway", tag: undefined });
  });
});

describe("the Deploy commands", () => {
  const script = parseBuildScript(BUILD_SH)!;
  const base = { outRoot: "C:\\w\\.gearbox\\shop\\prod", script, chart: "helm/shop", release: "shop", namespace: "shop" };

  it("builds as build.sh would, without sh, and keeps images local without a registry", () => {
    const commands = deployCommands({ ...base, registry: undefined, kubeContext: "kind-local" });
    expect(commands.build[0]).toBe(
      'docker build --ignorefile "C:/w/.gearbox/shop/prod/docker/.dockerignore" -f "C:/w/.gearbox/shop/prod/docker/api-gateway/Dockerfile" -t gbx-api-gateway:0.1.0 "C:/w/.gearbox/shop/prod/docker/../../../../.."',
    );
    expect(commands.push).toEqual([]);
    expect(commands.install).toBe('helm upgrade --install shop "C:/w/.gearbox/shop/prod/helm/shop" --namespace shop --create-namespace --kube-context kind-local');
  });

  it("pushes to the profile's registry and points the chart at it", () => {
    const commands = deployCommands({ ...base, registry: "ghcr.io/acme", kubeContext: "dev" });
    expect(commands.build[1]).toContain("-t ghcr.io/acme/gbx-worker:0.1.0");
    expect(commands.push).toEqual(["docker push ghcr.io/acme/gbx-api-gateway:0.1.0", "docker push ghcr.io/acme/gbx-worker:0.1.0"]);
    expect(commands.install).toContain("--set api-gateway.image.repository=ghcr.io/acme/gbx-api-gateway --set worker.image.repository=ghcr.io/acme/gbx-worker");
    expect(commands.template).toBe(
      'helm template shop "C:/w/.gearbox/shop/prod/helm/shop" --namespace shop --set api-gateway.image.repository=ghcr.io/acme/gbx-api-gateway --set worker.image.repository=ghcr.io/acme/gbx-worker',
    );
  });

  it("offers no install without a kube context", () => {
    expect(deployCommands({ ...base, registry: undefined }).install).toBeUndefined();
  });
});

describe("the organization's environments", () => {
  const prod = { id: "e-prod", name: "prod", namespace: "studio-web-prod", registry: "ghcr.io/acme", protected: true };
  const stage = { id: "e-stage", name: "stage", namespace: "studio-web-stage", registry: "", protected: false };
  const targets = { projectId: "p", environments: [stage, prod], bound: { prod: "e-prod" } };

  it("start on the environment the profile is bound to, then the first, then a kube context", () => {
    expect(defaultTarget(targets, "prod", ["kind"], undefined)).toEqual({ kind: "environment", id: "e-prod" });
    expect(defaultTarget(targets, "other", ["kind"], undefined)).toEqual({ kind: "environment", id: "e-stage" });
    expect(defaultTarget(undefined, "prod", ["kind", "dd"], "dd")).toEqual({ kind: "context", name: "dd" });
    expect(defaultTarget(undefined, "prod", [], undefined)).toBeUndefined();
  });

  it("round-trip through the select's value", () => {
    for (const t of [{ kind: "environment", id: "e1" }, { kind: "context", name: "kind-kind" }] as const) {
      expect(parseTarget(targetValue(t))).toEqual(t);
    }
    expect(parseTarget("junk")).toBeUndefined();
    expect(targetEnvironment(targets, { kind: "environment", id: "e-prod" })).toBe(prod);
    expect(targetEnvironment(targets, { kind: "context", name: "x" })).toBeUndefined();
  });

  it("are asked for with the images as generated and only a real commit", () => {
    const script = { contextFromDocker: "..", images: [{ app: "api", image: "studio-web/api:0.1.0" }] };
    const body = deployRequest({ environment: prod, profile: "prod", product: "studio-web", commit: "ea964f9", script, chart: "H4sI" });
    expect(body).toEqual({
      environment_id: "e-prod",
      profile: "prod",
      product: "studio-web",
      commit: "ea964f9",
      images: [{ app: "api", image: "studio-web/api:0.1.0" }],
      chart: "H4sI",
    });
    expect(deployRequest({ environment: prod, profile: "prod", product: "p", commit: "main", script, chart: "" }).commit).toBeUndefined();
    // The build it came from (ADR-0045 §4), when it is an id the server takes.
    expect(deployRequest({ environment: prod, profile: "prod", product: "p", build: "b-mfx1-0a0b0c0d", script, chart: "" }).build).toBe(
      "b-mfx1-0a0b0c0d",
    );
    expect(deployRequest({ environment: prod, profile: "prod", product: "p", build: "no", script, chart: "" }).build).toBeUndefined();
  });

  it("say whether the deploy waits for an approval", () => {
    expect(deployAnswer("awaiting_approval", "prod", "ns")).toMatch(/approval/);
    expect(deployAnswer("queued", "stage", "ns")).toMatch(/deploying into stage/);
  });
});
